"use client";

// Brief history.md #23 (cm-history). Guerry's 1830s literacy (percent of army conscripts who could read and write)
// for France's 86 departments, shaded on today's department outlines (stand-ins; the mapping is in gen.mjs).
// Data: departments.json, generated by gen.mjs from the pinned Guerry.csv and france-departements-simplifiee.geojson
// (company/domains/briefs/checks/history-data.mjs: guerry, frdep). Every number on the stage is computed here from
// departments.json rows, as in history-cycle2-check.mjs section 23: N+E mean 55.2, S+W+C 28.8, all 86 39.26
// (unweighted means of departments), Meuse 74, Corrèze 12, Seine 71. Outlines 06, 73, 74 have no value (hatched).
// Projection: conic equal-area (parallels 44 and 49 N, centred on 3 E), from d3-geo via @/kit/geo. Areas are
// not compared on this stage.
// Presets in DOM order (no Reset): North and east (milestone ne), South, west and centre (swc), Paris (Seine),
// Most and least literate (ext). The reveal quotes ne, swc and ext; the three means stay in the readout row and
// the Meuse / Corrèze labels stay on the map once reached, so the quoted values are on the stage at the reveal.
// ext is a third milestone beyond the brief's two (demo-standard: every number the reveal names is gated by a
// milestone); recorded in company/reviews/literacy-split-france/build.md.

import { useId, useMemo, useState } from "react";
import type { Feature, FeatureCollection, Geometry, MultiLineString } from "geojson";
import { Lesson } from "@/kit/Lesson";
import { Milestones } from "@/kit/milestones";
import { Control, Readout, Row } from "@/kit/controls";
import { geoConicEqualArea, geoPath } from "@/kit/geo";
import data from "./departments.json";
import s from "./styles.module.css";

type Dept = { dept: number; region: string; name: string; lit: number };
type Props = { code: string; g: number | null };
const ROWS = data.rows as Dept[];
const FEATURES = data.features as unknown as Feature<Geometry, Props>[];
const LINES = data.lines as unknown as Record<"ne" | "swc", MultiLineString>;
const BY = new Map(ROWS.map((r) => [r.dept, r]));

const mean = (rs: Dept[]) => rs.reduce((t, r) => t + r.lit, 0) / rs.length;
const inNE = (r: Dept) => r.region === "N" || r.region === "E";
const inSWC = (r: Dept) => r.region === "S" || r.region === "W" || r.region === "C";
const NE = ROWS.filter(inNE);
const SWC = ROWS.filter(inSWC);
const MEAN_NE = Math.round(mean(NE));
const MEAN_SWC = Math.round(mean(SWC));
const MEAN_ALL = Math.round(mean(ROWS));
const HI = ROWS.reduce((a, r) => (r.lit > a.lit ? r : a));
const LO = ROWS.reduce((a, r) => (r.lit < a.lit ? r : a));
const SEINE = ROWS.find((r) => r.name === "Seine")!;
const SHOW_NAME: Record<string, string> = { Correze: "Corrèze" };
const nameOf = (r: Dept) => SHOW_NAME[r.name] ?? r.name;

// five shading steps, darkest = most literate
// Colours mix the domain colour with the card background (low) or the text colour (high), so the order reads in
// light and dark themes: the further from the background, the more literate.
const STEPS = [
  { min: 65, label: "65–74", fill: "color-mix(in srgb, var(--domain) 50%, var(--fg))" },
  { min: 50, label: "50–64", fill: "color-mix(in srgb, var(--domain) 85%, var(--fg))" },
  { min: 35, label: "35–49", fill: "color-mix(in srgb, var(--domain) 70%, var(--bg-2))" },
  { min: 20, label: "20–34", fill: "color-mix(in srgb, var(--domain) 42%, var(--bg-2))" },
  { min: 0, label: "12–19", fill: "color-mix(in srgb, var(--domain) 16%, var(--bg-2))" },
];
const stepOf = (lit: number) => STEPS.findIndex((st) => lit >= st.min);

type Mode = "ne" | "swc" | "paris" | "ext";
const MILESTONES = ["ne", "swc", "ext"] as const;
const PRESETS: { id: Mode; label: string }[] = [
  { id: "ne", label: "North and east" },
  { id: "swc", label: "South, west and centre" },
  { id: "paris", label: "Paris (Seine)" },
  { id: "ext", label: "Most and least literate" },
];

const W = 340;
const H = 252;

function Stage({ locked, reach, mode, pick, seen }: {
  locked: boolean;
  reach: (n: string) => void;
  mode: Mode | null;
  pick: (m: Mode) => void;
  seen: Set<Mode>;
}) {
  const hatch = `hatch-${useId().replace(/[^a-zA-Z0-9-]/g, "")}`;
  const { path, xy } = useMemo(() => {
    const fc: FeatureCollection<Geometry, Props> = { type: "FeatureCollection", features: FEATURES };
    const projection = geoConicEqualArea().parallels([44, 49]).rotate([-3, 0]).fitExtent([[80, 4], [W - 4, H - 4]], fc);
    const g = geoPath(projection);
    return {
      path: (o: Parameters<typeof g>[0]) => g(o) ?? "",
      xy: (o: Feature<Geometry, Props>) => g.centroid(o),
    };
  }, []);
  const press = (m: Mode) => {
    if (locked || m === mode) return;
    pick(m);
    reach(m);
  };

  const active = locked ? null : mode;
  const named = (code: string) => {
    const f = FEATURES.find((x) => x.properties.code === code)!;
    return xy(f);
  };
  const seineCodes = new Set(["75", "92", "93", "94"]);
  const code2 = (r: Dept) => String(r.dept).padStart(2, "0");
  const showExt = !locked && seen.has("ext");
  const [hx, hy] = named(code2(HI));
  const [lx, ly] = named(code2(LO));
  const [px, py] = named("75");

  const label = locked
    ? "Outline map of France's departments, not yet shaded"
    : `France's departments shaded by the share of conscripts who could read and write, from 12% to 74%${active ? `; ${PRESETS.find((p) => p.id === active)!.label} picked` : ""}`;

  return (
    <div className={s.wrap}>
      <div className={s.pic}>
        <svg viewBox={`0 0 ${W} ${H}`} className="stage-svg" role="img" aria-label={label}>
          <defs>
            <pattern id={hatch} width={4} height={4} patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
              <line x1={0} y1={0} x2={0} y2={4} className={s.hatchLine} />
            </pattern>
          </defs>
          {FEATURES.map((f) => {
            const r = f.properties.g === null ? undefined : BY.get(f.properties.g);
            const fill = locked ? "color-mix(in srgb, var(--muted) 22%, var(--bg-2))" : r ? STEPS[stepOf(r.lit)].fill : `url(#${hatch})`;
            return <path key={f.properties.code} d={path(f)} style={{ fill }} className={s.dept} />;
          })}
          {active === "ne" && <path d={path(LINES.ne)} className={s.region} />}
          {active === "swc" && <path d={path(LINES.swc)} className={s.region} />}
          {active === "paris" &&
            FEATURES.filter((f) => seineCodes.has(f.properties.code)).map((f) => (
              <path key={`s${f.properties.code}`} d={path(f)} className={s.pick} />
            ))}
          {active === "paris" && (
            <>
              <line x1={px} y1={py} x2={px - 36} y2={py - 26} className={s.leader} />
              <text x={px - 38} y={py - 29} textAnchor="end" className={`${s.name} ${s.halo}`}>Seine {SEINE.lit}%</text>
            </>
          )}
          {active === "ext" &&
            FEATURES.filter((f) => f.properties.code === code2(HI) || f.properties.code === code2(LO)).map((f) => (
              <path key={`e${f.properties.code}`} d={path(f)} className={s.pick} />
            ))}
          {showExt && (
            <>
              <text x={hx} y={hy - 9} textAnchor="middle" className={`${s.name} ${s.halo}`}>{nameOf(HI)} {HI.lit}%</text>
              <text x={lx} y={ly - 9} textAnchor="middle" className={`${s.name} ${s.halo}`}>{nameOf(LO)} {LO.lit}%</text>
            </>
          )}
          {!locked && (
            <g>
              {["Conscripts", "who could", "read and", "write, %"].map((t, i) => (
                <text key={t} x={2} y={13 + i * 13} className={s.legendTitle}>{t}</text>
              ))}
              {STEPS.map((st, i) => (
                <g key={st.min}>
                  <rect x={2} y={60 + i * 16} width={15} height={12} style={{ fill: st.fill }} className={s.swatch} />
                  <text x={21} y={70 + i * 16} className={s.legend}>{st.label}</text>
                </g>
              ))}
              <rect x={2} y={142} width={15} height={12} fill={`url(#${hatch})`} className={s.swatch} />
              {["no value", "in Guerry's", "table"].map((t, i) => (
                <text key={t} x={21} y={152 + i * 13} className={s.legend}>{t}</text>
              ))}
            </g>
          )}
          {["Conic equal-area", "projection;", "today's outlines"].map((t, i) => (
            <text key={t} x={2} y={H - 32 + i * 13} className={s.proj}>{t}</text>
          ))}
        </svg>
      </div>
      <div className={s.presets}>
        {PRESETS.map((p) => (
          <Control key={p.id} disabled={locked} className={`${s.tap} ${!locked && mode === p.id ? "active" : ""}`}
            aria-pressed={!locked && mode === p.id} onClick={() => press(p.id)}>
            {p.label}
          </Control>
        ))}
      </div>
      <Row>
        <Readout label="North and east" value={!locked && seen.has("ne") ? `${MEAN_NE}%` : "–"} />
        <Readout label="South, west, centre" value={!locked && seen.has("swc") ? `${MEAN_SWC}%` : "–"} />
        <Readout label="All 86" value={locked ? "–" : `${MEAN_ALL}%`} />
      </Row>
    </div>
  );
}

export default function LiteracySplitFrance({ slug }: { slug: string }) {
  const [mode, setMode] = useState<Mode | null>(null);
  const [seen, setSeen] = useState<Set<Mode>>(() => new Set());
  const pick = (m: Mode) => {
    setMode(m);
    setSeen((prev) => (prev.has(m) ? prev : new Set(prev).add(m)));
  };
  return (
    <Lesson
      slug={slug}
      predict={{
        question:
          "Across France's 86 departments in the 1830s, about 39% of army conscripts could read and write, on average. Which part was most literate?",
        options: ["The south", "The north and east", "The west"],
        answer: 1,
      }}
      exploreHint="Press each part of France, then the most and least literate departments."
      minInteractions={MILESTONES.length}
      reveal={() => (
        <>
          <p>
            In Guerry&apos;s north and east, departments averaged {MEAN_NE}% of conscripts who could read and write; in
            the south, west and centre, {MEAN_SWC}%. The extremes were {nameOf(HI)}, {HI.lit}%, and {nameOf(LO)},{" "}
            {LO.lit}%. An average of {MEAN_ALL}% across departments hid two very different Frances.
          </p>
          <p>
            Where it stops: these are young men called up for the army, not everyone, and today&apos;s department
            outlines stand in for those of the 1830s.
          </p>
        </>
      )}
    >
      {({ locked, interact }) => (
        <Milestones interact={interact} names={MILESTONES}>
          {(reach) => <Stage locked={locked} reach={reach} mode={mode} pick={pick} seen={seen} />}
        </Milestones>
      )}
    </Lesson>
  );
}
